      return {
        ...theme,
        creator: {
          profileId: creator.id,
          profileName: creator.name,
          avatarBase64: creator.avatarBase64
        },
        isFavorited: favorites.includes(theme.id)
      };
    });

    return {
      themes: themesWithCreator,
      total: filtered.length,
      page,
      limit,
      hasMore: end < filtered.length
    };
